begin;
-- Synthetic fixture explicitly activates Community; production defaults stay closed.
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
('c1600000-0000-4000-8000-000000000001','moderation-reporter@mizyun.test'),
('c1600000-0000-4000-8000-000000000002','moderation-subject@mizyun.test'),
('c1600000-0000-4000-8000-000000000003','moderation-staff-a@mizyun.test'),
('c1600000-0000-4000-8000-000000000004','moderation-staff-b@mizyun.test');
update public.profiles set birth_year=1990 where id::text like 'c1600000-%';
insert into public.community_moderation_staff(user_id,active) values('c1600000-0000-4000-8000-000000000003',true),('c1600000-0000-4000-8000-000000000004',true);
create temporary table moderation_test_state(receipt uuid,report uuid,appeal uuid);
grant all on moderation_test_state to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000001';
set local request.jwt.claims='{"aal":"aal1"}';
select * from public.community_save_profile('moderation_a','Reporter','RA',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select * from public.community_save_profile('moderation_b','Subject','SB',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_moderation_queue()$$,'P0001','community_access_denied','Ordinary member cannot inspect moderation queue');
select throws_ok($$select * from public.community_moderation_appeals_queue()$$,'P0001','community_access_denied','Ordinary member cannot inspect pending appeals');
select throws_ok($$insert into public.community_reports(reporter_user_id,target_type,target_id,reason) values(auth.uid(),'profile','c1600000-0000-4000-8000-000000000002','spam')$$,'42501',null,'Direct report insert cannot bypass quota/visibility');
select throws_ok($$select * from public.community_issue_report_receipt('profile','c1600000-0000-4000-8000-000000000004')$$,'P0001','community_unavailable','Cannot mint arbitrary profile receipt');
insert into moderation_test_state(receipt) select id from public.community_issue_report_receipt('profile','c1600000-0000-4000-8000-000000000002');
select is((select count(*) from public.community_report_receipts_for_caller()),1::bigint,'Caller can retrieve own opaque receipt');
select * from public.community_withdraw_profile();
update moderation_test_state set report=(select id from public.community_submit_report('profile','c1600000-0000-4000-8000-000000000002','harassment','offensive quote',(select receipt from moderation_test_state)));
select lives_ok($$select * from public.community_submit_report('profile','c1600000-0000-4000-8000-000000000002','harassment','more evidence',(select receipt from moderation_test_state))$$,'Withdrawn reporter can append receipt-backed evidence');
select is((select count(*) from public.community_reports),1::bigint,'Duplicate report is one case');
select is((select priority from public.community_reports),'urgent','Harassment containing possible threats receives urgent priority');
select throws_ok($$select staff_notes from public.community_reports$$,'42501',null,'Owner cannot inspect staff notes');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select is((select count(*) from public.community_report_receipts_for_caller()),0::bigint,'Another user cannot retrieve receipt');
select is((select count(*) from public.community_get_report((select report from moderation_test_state))),0::bigint,'Subject cannot inspect a known pending report ID');
select throws_ok($$select * from public.community_submit_report('profile','c1600000-0000-4000-8000-000000000002','spam',null,(select receipt from moderation_test_state))$$,'P0001','community_unavailable','Another caller cannot use stolen receipt');
select throws_ok($$select * from public.community_create_moderation_appeal((select report from moderation_test_state),'premature')$$,'P0001','community_access_denied','No appeal of unacted case');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000003';
select throws_ok($$select * from public.community_moderation_queue()$$,'P0001','community_access_denied','Registered staff requires AAL2');
set local request.jwt.claims='{"aal":"aal2"}';
select is((select count(*) from public.community_moderation_queue()),1::bigint,'Named AAL2 staff sees scoped queue');
select throws_ok($$select * from public.community_apply_moderation_action((select report from moderation_test_state),null,'Invalid',null,null)$$,'P0001','community_invalid_action','Null action cannot bypass enum validation');
reset role;set local request.jwt.claim.role='service_role';
create function pg_temp.fail_moderation_audit() returns trigger language plpgsql as $$begin raise exception 'synthetic_audit_failure';end $$;
create trigger moderation_test_fail_audit before insert on public.community_moderation_actions for each row execute function pg_temp.fail_moderation_audit();
set local role authenticated;set local request.jwt.claim.role='authenticated';
select throws_ok($$select * from public.community_apply_moderation_action((select report from moderation_test_state),'suspend','Harassment','internal evidence',7)$$,'P0001','synthetic_audit_failure','Failed audit rolls back full staff transaction');
reset role;set local request.jwt.claim.role='service_role';
select is((select status from public.community_reports where id=(select report from moderation_test_state)),'submitted','Audit failure leaves report pending');
select is((select count(*) from public.community_moderation_sanctions),0::bigint,'Audit failure leaves no sanction');
select is((select status from public.community_profiles where user_id='c1600000-0000-4000-8000-000000000002'),'active','Audit failure does not withdraw subject');
drop trigger moderation_test_fail_audit on public.community_moderation_actions;
set local role authenticated;set local request.jwt.claim.role='authenticated';
select lives_ok($$select * from public.community_claim_report((select report from moderation_test_state))$$,'Staff claims report');
select is((select status from public.community_moderation_queue() where id=(select report from moderation_test_state)),'under_review','Claim enters review state');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000004';
select throws_ok($$select * from public.community_claim_report((select report from moderation_test_state))$$,'P0001','community_conflict','Another operator cannot steal claim');
select throws_ok($$select * from public.community_apply_moderation_action((select report from moderation_test_state),'warn','Contested',null,null)$$,'P0001','community_conflict','Another operator cannot decide assigned report');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000003';
select lives_ok($$select * from public.community_apply_moderation_action((select report from moderation_test_state),'suspend','Harassment','internal evidence',7)$$,'Atomic staff action');
select throws_ok($$select * from public.community_apply_moderation_action((select report from moderation_test_state),'ban','second action',null,null)$$,'P0001','community_conflict','Resolved case cannot receive duplicate sanction');
select is((select count(*) from public.community_moderation_queue()),0::bigint,'Default queue excludes old urgent resolved case');
select is((select count(*) from public.community_moderation_queue('resolved')),1::bigint,'Explicit archive filter retains resolved case');
select is((select count(*) from public.community_get_report((select report from moderation_test_state))),1::bigint,'Named staff can inspect resolved evidence');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select is((select status from public.community_get_profile(auth.uid())),'withdrawn','Sanction withdraws community enrollment');
select ok((select suspension_expires_at=now()+interval '7 days' and decision_reason is null from public.community_moderation_notices()),'Subject gets sanction expiry without staff free text');
select throws_ok($$select * from public.community_save_profile('moderation_b','Subject','SB',null,true,true,'2026-09-30')$$,'P0001','community_unavailable','Sanction cannot be bypassed by fresh consent');
select is((select count(*) from public.community_moderation_notices()),1::bigint,'Subject sees own decision notice');
select ok((select notes is null and staff_notes is null and assigned_to is null from public.community_moderation_notices()),'Subject notice withholds reporter notes and operator');
update moderation_test_state set appeal=(select id from public.community_create_moderation_appeal((select report from moderation_test_state),'Please review'));
select throws_ok($$select reviewer_notes from public.community_moderation_appeals$$,'42501',null,'Owner cannot inspect reviewer notes');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000003';
select throws_ok($$select * from public.community_resolve_moderation_appeal((select appeal from moderation_test_state),'approved','own review')$$,'P0001','community_access_denied','Original operator cannot review own sanction');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000004';
select is((select count(*) from public.community_moderation_appeals_queue()),1::bigint,'Independent staff can discover pending appeal');
select lives_ok($$select * from public.community_resolve_moderation_appeal((select appeal from moderation_test_state),'approved','independent review')$$,'Independent AAL2 reviewer can reverse');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select is((select status from public.community_get_profile(auth.uid())),'withdrawn','Appeal reversal never resurrects profile');
reset role;set local request.jwt.claim.role='service_role';
select * from public.community_withdrawal_batch('c1600000-0000-4000-8000-000000000002',1);
set local role authenticated;set local request.jwt.claim.role='authenticated';
select lives_ok($$select * from public.community_save_profile('moderation_b','Subject','SB',null,true,true,'2026-09-30')$$,'Explicit reenrollment after reversal is permitted');
reset role;set local request.jwt.claim.role='service_role';
select is((select report_count from public.community_report_usage where user_id='c1600000-0000-4000-8000-000000000001'),1,'Duplicates do not consume quota');
select is((select count(*) from public.community_moderation_actions where action in ('suspend','reverse')),2::bigint,'Action and reversal both audited');
select ok(exists(select 1 from public.community_moderation_actions where action='claim' and staff_operator='c1600000-0000-4000-8000-000000000003'),'Claim records named operator');
select ok(exists(select 1 from public.community_moderation_actions where action='inspect' and reason='Moderation queue inspection'),'Staff queue evidence reads audited');
select ok(exists(select 1 from public.community_moderation_actions where action='inspect' and reason='Case evidence inspection'),'Individual evidence read audited');
select ok(exists(select 1 from public.community_moderation_actions where action='inspect' and reason='Appeal queue inspection'),'Appeal queue reads audited');
update public.community_report_usage set report_count=10 where user_id='c1600000-0000-4000-8000-000000000001';
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000001';
select throws_ok($$select * from public.community_submit_report('profile','c1600000-0000-4000-8000-000000000002','spam',null,(select receipt from moderation_test_state))$$,'P0001','community_rate_limited','Atomic daily quota rejects eleventh case');
reset role;set local request.jwt.claim.role='service_role';
update public.community_report_receipts set expires_at=now()-interval '1 second';
set local role authenticated;set local request.jwt.claim.role='authenticated';
select throws_ok($$select * from public.community_submit_report('profile','c1600000-0000-4000-8000-000000000002','spam',null,(select receipt from moderation_test_state))$$,'P0001','community_unavailable','Expired receipt cannot authorize withdrawn reporter');
reset role;set local request.jwt.claim.role='service_role';
insert into public.community_relationships(follower_user_id,target_user_id,status) values('c1600000-0000-4000-8000-000000000001','c1600000-0000-4000-8000-000000000002','pending');
update public.community_relationships set status='approved' where follower_user_id='c1600000-0000-4000-8000-000000000001';
select is((select status from public.community_relationships where follower_user_id='c1600000-0000-4000-8000-000000000001'),'approved','Receipt trigger never cancels relationship update');
select ok((select count(*)>1 from public.community_report_receipts where user_id='c1600000-0000-4000-8000-000000000001'),'Relationship update captures durable caller receipt');
select ok(not exists(select 1 from public.community_report_receipts where evidence_snapshot ? 'sourceWorkoutId' or evidence_snapshot ? 'source_workout_id'),'Receipts contain no private workout linkage');
-- A valid invitation supplies reporting authority for a discovery-off profile,
-- while arbitrary and expired bearers never mint that authority.
delete from public.community_relationships where follower_user_id='c1600000-0000-4000-8000-000000000001';
update public.community_report_usage set report_count=0 where user_id='c1600000-0000-4000-8000-000000000001';
set local role authenticated;set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select * from public.community_save_profile('moderation_b','Subject','SB',null,false);
select * from public.community_create_invitation('1234567890123456789012',1);
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000001';
reset role;set local request.jwt.claim.role='service_role';
select * from public.community_withdrawal_batch('c1600000-0000-4000-8000-000000000001',1);
set local role authenticated;set local request.jwt.claim.role='authenticated';
select * from public.community_save_profile('moderation_a','Reporter','RA',null,false,true,'2026-09-30');
select is((select count(*) from public.community_get_profile('c1600000-0000-4000-8000-000000000002')),0::bigint,'Discovery-off inviter has no profile lookup authority');
reset role;set local request.jwt.claim.role='service_role';
delete from public.community_report_receipts where user_id='c1600000-0000-4000-8000-000000000001';
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select count(*) from public.community_resolve_invitation('bad-invite')),0::bigint,'Unknown invitation resolves nothing');
select is((select count(*) from public.community_report_receipts_for_caller()),0::bigint,'Unknown invitation creates no receipt');
select is((select count(*) from public.community_resolve_invitation('1234567890123456789012')),1::bigint,'Valid invite resolves minimal hidden inviter identity');
select is((select count(*) from public.community_report_receipts_for_caller()),1::bigint,'Actual valid resolution captures caller receipt');
select lives_ok($$select * from public.community_submit_report('profile','c1600000-0000-4000-8000-000000000002','spam','Invitation evidence')$$,'Hidden inviter report auto-selects owned receipt');
reset role;set local request.jwt.claim.role='service_role';
select ok((select evidence_snapshot->>'bio' is null from public.community_report_receipts where user_id='c1600000-0000-4000-8000-000000000001'),'Invite receipt never captures unviewed bio');
select * from finish();
rollback;
